-- Executive Hiring Intelligence — global seed data.
--
-- Global library rows (organization_id NULL): 24 evidence-based executive
-- competencies and 8 role templates. Tenants read these via the
-- exec_*_select policies; org-private rows can be added later without
-- touching this data.
--
-- Indicators are observable evidence only — no psychological labels, no
-- protected-characteristic proxies. ON CONFLICT DO NOTHING keeps the
-- migration re-runnable.

-- ---------------------------------------------------------------------------
-- Competency library
-- ---------------------------------------------------------------------------

INSERT INTO public.executive_competencies
  (key, name, category, definition, positive_indicators, negative_indicators)
VALUES
  -- Leadership
  ('executive_communication', 'Executive Communication', 'leadership',
   'Communicates strategy, trade-offs, and status crisply to executive and board audiences.',
   ARRAY['Has presented strategy or major decisions to an executive team or board with documented outcomes',
         'Translates specialist detail into business terms for non-specialist stakeholders'],
   ARRAY['Relies on jargon when pressed for specifics',
         'Cannot articulate the rationale behind past decisions in plain terms']),
  ('organizational_design', 'Organizational Design', 'leadership',
   'Designs and evolves organization structures matched to strategy, stage, and scale.',
   ARRAY['Has restructured an organization with a stated before/after rationale and measured outcomes',
         'Has designed team topologies for a specific growth phase and revisited them as scale changed'],
   ARRAY['Org changes made without stated rationale or follow-up measurement']),
  ('talent_magnetism', 'Talent Attraction & Development', 'leadership',
   'Attracts, develops, and retains senior talent; builds leadership benches.',
   ARRAY['Can name leaders they hired or developed who were later promoted',
         'Prior teams show low regretted attrition over multi-year periods'],
   ARRAY['Cannot name leaders they developed',
         'Pattern of senior-team churn following their arrival']),
  ('decision_quality', 'Decision Quality Under Uncertainty', 'leadership',
   'Makes evidence-weighted, timely decisions with incomplete information and owns reversals.',
   ARRAY['Can walk through two or three consequential decisions including the information available at the time',
         'Documents decision rationale and revisits decisions when evidence changes'],
   ARRAY['Post-hoc rationalization of outcomes',
         'Cannot describe the alternatives that were considered and rejected']),
  ('change_leadership', 'Change Leadership', 'leadership',
   'Leads organizations through significant change with measurable adoption.',
   ARRAY['Led a named change program with measurable adoption or outcome metrics',
         'Can describe resistance encountered and how it was addressed'],
   ARRAY['Change programs stalled or were abandoned without documented lessons']),
  ('cross_functional_influence', 'Cross-Functional Influence', 'leadership',
   'Wins alignment and commitment across peer functions without direct authority.',
   ARRAY['Shipped outcomes that required sustained commitment from peer functions',
         'Peer stakeholders from prior roles corroborate collaborative delivery'],
   ARRAY['Track record limited to outcomes within their own reporting line']),

  -- Functional
  ('technology_strategy', 'Technology Strategy', 'functional',
   'Sets multi-year technology direction explicitly tied to business outcomes.',
   ARRAY['Authored a technology strategy that named business outcomes and was funded',
         'Can explain build-vs-buy and platform decisions with their commercial context'],
   ARRAY['Technology choices described without reference to business constraints or outcomes']),
  ('engineering_excellence', 'Engineering Excellence', 'functional',
   'Operates high-performing engineering organizations with visible delivery, quality, and reliability practice.',
   ARRAY['Can cite the delivery, quality, or reliability measures their org tracked and how they moved',
         'Introduced engineering practices with before/after evidence'],
   ARRAY['No measurable definition of engineering health in prior roles']),
  ('product_strategy', 'Product Strategy', 'functional',
   'Makes portfolio and roadmap choices grounded in customer and market evidence.',
   ARRAY['Can trace a major roadmap bet to the customer or market evidence behind it',
         'Has killed or pivoted initiatives based on evidence, not sunk cost'],
   ARRAY['Roadmap described as a feature list without underlying strategic logic']),
  ('ai_strategy', 'AI Strategy & Governance', 'functional',
   'Evaluates, deploys, and governs AI capabilities responsibly and with business justification.',
   ARRAY['Deployed AI capabilities with stated success criteria and governance controls',
         'Can articulate where AI was deliberately not used and why'],
   ARRAY['Describes AI adoption in trend language without concrete use cases or controls']),
  ('data_governance', 'Data Governance', 'functional',
   'Establishes data quality, lineage, access, and privacy compliance at scale.',
   ARRAY['Implemented data governance that passed internal or external audit',
         'Can describe specific data-quality or privacy incidents and the systemic fixes'],
   ARRAY['Treats data governance as a documentation exercise without operational teeth']),
  ('financial_stewardship', 'Financial Stewardship', 'functional',
   'Owns budgets with demonstrated cost-value discipline and forecasting accuracy.',
   ARRAY['Managed budgets of comparable scale with documented variance discipline',
         'Can explain a significant cost decision including what was protected and why'],
   ARRAY['Cannot state the size or shape of budgets previously owned']),
  ('operational_excellence', 'Operational Excellence', 'functional',
   'Builds repeatable operating cadences, processes, and execution rigor.',
   ARRAY['Installed operating cadences (planning, review, escalation) that survived their tenure',
         'Can show a process they simplified with measured effect'],
   ARRAY['Operating model described only in terms of meetings held']),
  ('commercial_acumen', 'Commercial Acumen', 'functional',
   'Understands revenue mechanics and partners effectively with go-to-market functions.',
   ARRAY['Can explain the revenue model and unit economics of prior businesses accurately',
         'Shipped work with measurable commercial impact co-owned with sales or marketing'],
   ARRAY['Frames commercial topics as someone else''s responsibility']),

  -- Operating
  ('zero_to_one_building', 'Zero-to-One Building', 'operating',
   'Built functions, products, or platforms from scratch with limited resources.',
   ARRAY['Started a function or product from nothing and can name the first hires and first milestones',
         'Made explicit scrappiness trade-offs appropriate to the stage'],
   ARRAY['Experience limited to inheriting mature teams and systems']),
  ('scaling_systems', 'Scaling Through Growth', 'operating',
   'Scaled teams, systems, and processes through rapid growth inflections.',
   ARRAY['Operated through a documented headcount or volume inflection (e.g. 3x within two years)',
         'Can describe what broke during scaling and how it was re-architected'],
   ARRAY['Describes scaling only in terms of hiring numbers']),
  ('enterprise_operating_experience', 'Enterprise Operating Experience', 'operating',
   'Operates effectively within large-organization constraints: procurement, audit, matrixed stakeholders.',
   ARRAY['Delivered outcomes inside organizations with formal procurement, audit, and compliance gates',
         'Can name the governance forums they operated through'],
   ARRAY['Visible frustration with enterprise process substituting for a strategy to work within it']),
  ('pnl_ownership', 'P&L Ownership', 'operating',
   'Holds direct profit-and-loss accountability for a business or business unit.',
   ARRAY['Owned a P&L and can state its size, margin profile, and their levers',
         'Made resourcing decisions with explicit P&L consequences'],
   ARRAY['Claims P&L ownership that was actually budget administration']),
  ('transformation_delivery', 'Transformation Delivery', 'operating',
   'Delivers named multi-year transformation programs to completion.',
   ARRAY['Named transformation program delivered with published milestones and outcomes',
         'Can describe scope cuts and sequencing decisions made under pressure'],
   ARRAY['Transformation experience limited to strategy decks without delivery accountability']),
  ('m_and_a_integration', 'M&A and Integration', 'operating',
   'Contributes to diligence and delivers post-merger integration.',
   ARRAY['Played a named role in diligence or integration with attributable outcomes',
         'Can describe an integration decision that preserved or destroyed value'],
   ARRAY['M&A exposure limited to being at a company while a deal happened']),

  -- Governance
  ('board_engagement', 'Board Engagement', 'governance',
   'Prepares for, presents to, and builds working relationships with boards.',
   ARRAY['Regular board presenter with artifacts they authored',
         'Has managed a difficult board conversation and can describe the preparation'],
   ARRAY['Board exposure limited to attending as an observer']),
  ('regulatory_compliance', 'Regulatory Navigation', 'governance',
   'Operates in regulated environments and manages regulator relationships.',
   ARRAY['Operated under named regulatory regimes and can describe specific obligations they owned',
         'Managed an examination, remediation, or regulator interaction directly'],
   ARRAY['Treats regulation as an obstacle rather than an operating parameter']),
  ('risk_management', 'Risk Management', 'governance',
   'Identifies, quantifies, and mitigates enterprise and operational risk.',
   ARRAY['Built or operated a risk register with named mitigations and owners',
         'Can describe a risk they escalated early and what it cost or saved'],
   ARRAY['Risk framing is purely reactive — incidents first, controls after']),
  ('investor_relations', 'Investor & Owner Relations', 'governance',
   'Communicates credibly with investors, PE operators, and owners; manages expectations.',
   ARRAY['Presented operating results to investors or a PE operating partner',
         'Can describe a moment expectations had to be reset and how it was handled'],
   ARRAY['No direct exposure to owners or investors despite senior titles'])
ON CONFLICT DO NOTHING;

