-- Role templates
-- ---------------------------------------------------------------------------

INSERT INTO public.executive_role_templates
  (key, title, summary, role_family, intake_defaults, competency_weights)
VALUES
  ('cto_seed_saas', 'CTO — Seed-Stage SaaS',
   'Player-coach technical founder-adjacent leader: ships the product with a small team while laying just enough foundation to survive success.',
   'cto',
   '{"role_title": "Chief Technology Officer", "role_family": "cto", "industry": "Software / SaaS", "business_model": "B2B SaaS", "funding_stage": "Seed", "revenue_range": "$0-1M ARR", "employee_count": "5-25", "reporting_line": "CEO", "board_exposure": "Presents at board meetings when technology is on the agenda", "team_size": "2-10 engineers", "business_situation": "Pre-product-market-fit: speed of learning matters more than architectural purity.", "expected_90_day_outcomes": "Owns the codebase and delivery cadence; ships weekly; first key hire in motion.", "expected_first_year_outcomes": "Product velocity sustained through PMF search; team of 8-12 with a working hiring engine; no catastrophic technical debt.", "preferred_leadership_style": "Hands-on player-coach"}'::jsonb,
   '[{"competency_key": "zero_to_one_building", "weight": 90, "rationale": "The entire job is building from nothing with constrained resources."},
     {"competency_key": "engineering_excellence", "weight": 70, "rationale": "Enough rigor to move fast without breaking trust — not enterprise process."},
     {"competency_key": "technology_strategy", "weight": 65, "rationale": "Directional architecture bets matter, but strategy documents do not."},
     {"competency_key": "talent_magnetism", "weight": 75, "rationale": "First ten engineers determine the company ceiling."},
     {"competency_key": "decision_quality", "weight": 70, "rationale": "Weekly irreversible-feeling decisions with thin evidence."},
     {"competency_key": "financial_stewardship", "weight": 40, "rationale": "Budget is small; runway awareness suffices."}]'::jsonb),

  ('cto_growth_saas', 'CTO — Growth-Stage SaaS',
   'Scales the engineering organization and platform through rapid growth while keeping delivery credible to the board.',
   'cto',
   '{"role_title": "Chief Technology Officer", "role_family": "cto", "industry": "Software / SaaS", "business_model": "B2B SaaS", "funding_stage": "Series C+", "revenue_range": "$20-100M ARR", "employee_count": "200-1000", "reporting_line": "CEO", "board_exposure": "Standing board attendee; owns the technology section", "team_size": "60-250 engineers", "business_situation": "Post-PMF scaling: the systems and org that got here will not get to the next stage.", "expected_90_day_outcomes": "Credible read on org and platform health; leadership team assessed; scaling plan drafted.", "expected_first_year_outcomes": "Org redesigned for scale; delivery predictability restored; platform re-architecture funded and underway.", "preferred_leadership_style": "Org-builder who stays technically credible"}'::jsonb,
   '[{"competency_key": "scaling_systems", "weight": 90, "rationale": "The core mandate is surviving the growth inflection."},
     {"competency_key": "organizational_design", "weight": 80, "rationale": "Team topology is the primary scaling instrument."},
     {"competency_key": "engineering_excellence", "weight": 80, "rationale": "Predictable delivery at scale is the board-visible output."},
     {"competency_key": "technology_strategy", "weight": 70, "rationale": "Platform bets now determine cost structure at 5x scale."},
     {"competency_key": "talent_magnetism", "weight": 75, "rationale": "Must recruit a leadership bench, not just engineers."},
     {"competency_key": "board_engagement", "weight": 55, "rationale": "Regular board exposure; technology narrative must hold up."}]'::jsonb),

  ('cio_financial_institution', 'CIO — Mid-Sized Financial Institution',
   'Modernizes technology inside a regulated institution while keeping regulators, auditors, and the board confident.',
   'cio',
   '{"role_title": "Chief Information Officer", "role_family": "cio", "industry": "Financial Services", "business_model": "Regulated financial institution", "ownership_structure": "Public or mutual", "employee_count": "1000-10000", "regulatory_environment": "Prudential and conduct regulation; regular examinations", "reporting_line": "CEO or COO", "board_exposure": "Quarterly board and risk-committee reporting", "team_size": "150-600 technology staff", "business_situation": "Legacy modernization under regulatory scrutiny with an inflexible change budget.", "expected_90_day_outcomes": "Regulatory posture assessed; critical-system risk map produced; quick credibility wins identified.", "expected_first_year_outcomes": "Modernization roadmap approved by the board; audit findings trending down; delivery credibility with business lines restored.", "preferred_leadership_style": "Steady, governance-fluent, evidence-led"}'::jsonb,
   '[{"competency_key": "regulatory_compliance", "weight": 90, "rationale": "Regulatory standing is existential for the institution."},
     {"competency_key": "enterprise_operating_experience", "weight": 85, "rationale": "Must deliver through procurement, audit, and committee structures."},
     {"competency_key": "risk_management", "weight": 80, "rationale": "Technology risk is board-level risk here."},
     {"competency_key": "transformation_delivery", "weight": 75, "rationale": "Legacy modernization is the multi-year mandate."},
     {"competency_key": "technology_strategy", "weight": 70, "rationale": "Strategy must reconcile modernization with regulatory constraint."},
     {"competency_key": "board_engagement", "weight": 70, "rationale": "Quarterly board and risk-committee accountability."}]'::jsonb),

  ('cpo_growth_tech', 'CPO — Growth-Stage Technology Company',
   'Turns a founder-led product instinct into a durable product organization and evidence-driven portfolio strategy.',
   'cpo',
   '{"role_title": "Chief Product Officer", "role_family": "cpo", "industry": "Technology", "business_model": "SaaS or platform", "funding_stage": "Series B-D", "employee_count": "100-800", "reporting_line": "CEO", "board_exposure": "Presents product strategy to the board", "team_size": "15-80 product managers and designers", "business_situation": "Founder is stepping back from day-to-day product; portfolio decisions now exceed one person''s intuition.", "expected_90_day_outcomes": "Product org assessed; decision rights clarified with the founder; portfolio evidence base started.", "expected_first_year_outcomes": "Roadmap governed by evidence; product org retained and upgraded; at least one major bet validated or killed on the evidence.", "preferred_leadership_style": "Evidence-led, founder-compatible"}'::jsonb,
   '[{"competency_key": "product_strategy", "weight": 90, "rationale": "Portfolio choices are the core of the mandate."},
     {"competency_key": "cross_functional_influence", "weight": 80, "rationale": "Product outcomes require engineering and GTM commitment."},
     {"competency_key": "commercial_acumen", "weight": 75, "rationale": "Roadmap must connect to revenue mechanics."},
     {"competency_key": "scaling_systems", "weight": 70, "rationale": "Product org and process must scale with the company."},
     {"competency_key": "decision_quality", "weight": 70, "rationale": "Kill/pivot decisions define the tenure."},
     {"competency_key": "talent_magnetism", "weight": 65, "rationale": "Senior PM talent follows credible product leaders."}]'::jsonb),

  ('vp_engineering_series_b', 'VP Engineering — Series B',
   'Installs delivery predictability and a hiring engine while the founding CTO focuses on architecture and vision.',
   'vp_engineering',
   '{"role_title": "VP Engineering", "role_family": "vp_engineering", "industry": "Technology", "business_model": "SaaS", "funding_stage": "Series B", "employee_count": "50-200", "reporting_line": "CTO or CEO", "board_exposure": "Occasional; delivery metrics feed board reporting", "team_size": "20-60 engineers", "business_situation": "Post-Series-B scaling: delivery is slipping as headcount doubles.", "expected_90_day_outcomes": "Delivery cadence measured and stabilized; management layer assessed; hiring pipeline running.", "expected_first_year_outcomes": "Team roughly doubled without velocity collapse; management bench installed; predictable quarterly delivery.", "preferred_leadership_style": "Operational, people-first, metrics-literate"}'::jsonb,
   '[{"competency_key": "scaling_systems", "weight": 85, "rationale": "Doubling the team without breaking delivery is the job."},
     {"competency_key": "engineering_excellence", "weight": 85, "rationale": "Delivery predictability is the visible mandate."},
     {"competency_key": "organizational_design", "weight": 75, "rationale": "Management structure must be built, not inherited."},
     {"competency_key": "talent_magnetism", "weight": 75, "rationale": "Owns the hiring engine end to end."},
     {"competency_key": "operational_excellence", "weight": 65, "rationale": "Cadences and process rigor carry the scaling."},
     {"competency_key": "cross_functional_influence", "weight": 60, "rationale": "Partnership with product determines throughput."}]'::jsonb),

  ('coo_scaling_startup', 'COO — Operationally Scaling Startup',
   'Builds the operating machine — cadences, processes, and accountability — under a founder-CEO whose strengths lie elsewhere.',
   'coo',
   '{"role_title": "Chief Operating Officer", "role_family": "coo", "industry": "Technology or tech-enabled services", "funding_stage": "Series B-D", "employee_count": "100-600", "reporting_line": "CEO", "board_exposure": "Standing board attendee for operating review", "budget_scope": "Owns operating budget across functions", "business_situation": "Growth has outrun the operating model; the CEO needs a partner who makes the machine run.", "expected_90_day_outcomes": "Operating cadence installed; cross-functional accountability visible; top three operational fires owned.", "expected_first_year_outcomes": "Predictable operating rhythm; measurable efficiency gains; leadership team operating as a system.", "preferred_leadership_style": "Systematic, calm, high-accountability"}'::jsonb,
   '[{"competency_key": "operational_excellence", "weight": 90, "rationale": "The operating machine is the deliverable."},
     {"competency_key": "scaling_systems", "weight": 85, "rationale": "Every process must survive the next doubling."},
     {"competency_key": "organizational_design", "weight": 80, "rationale": "Accountability structure is the primary tool."},
     {"competency_key": "financial_stewardship", "weight": 75, "rationale": "Owns the operating budget and efficiency narrative."},
     {"competency_key": "pnl_ownership", "weight": 70, "rationale": "Operating decisions carry direct P&L consequence."},
     {"competency_key": "cross_functional_influence", "weight": 70, "rationale": "Runs the seams between every function."}]'::jsonb),

  ('chief_ai_officer_regulated', 'Chief AI Officer — Regulated Enterprise',
   'Builds AI capability and governance simultaneously inside an enterprise where a single ungoverned deployment can trigger regulatory consequences.',
   'chief_ai_officer',
   '{"role_title": "Chief AI Officer", "role_family": "chief_ai_officer", "industry": "Regulated enterprise (financial services, healthcare, energy)", "employee_count": "5000+", "regulatory_environment": "Sector regulation plus emerging AI-specific regulation", "reporting_line": "CEO, CIO, or Chief Data Officer", "board_exposure": "Board and risk-committee reporting on AI posture", "business_situation": "Board-level pressure to capture AI value; equal pressure to avoid regulatory or reputational failure.", "expected_90_day_outcomes": "AI inventory and risk posture established; governance framework drafted; two or three high-value, low-risk use cases in flight.", "expected_first_year_outcomes": "Governed AI platform serving multiple business lines; measurable value delivered; regulator-ready documentation standing.", "preferred_leadership_style": "Credible with both engineers and regulators"}'::jsonb,
   '[{"competency_key": "ai_strategy", "weight": 90, "rationale": "The mandate is AI value with governance, not experimentation."},
     {"competency_key": "regulatory_compliance", "weight": 85, "rationale": "AI deployments must survive regulatory scrutiny."},
     {"competency_key": "data_governance", "weight": 80, "rationale": "AI quality is bounded by data governance maturity."},
     {"competency_key": "risk_management", "weight": 75, "rationale": "Every model is an operating risk to be owned."},
     {"competency_key": "executive_communication", "weight": 70, "rationale": "Must translate AI posture for board and regulators."},
     {"competency_key": "change_leadership", "weight": 70, "rationale": "Adoption across business lines is a change program."}]'::jsonb),

  ('head_of_transformation_fi', 'Head of Transformation — Financial Institution',
   'Owns a named multi-year transformation program end to end: sequencing, delivery, stakeholder management, and the scars to prove it.',
   'transformation',
   '{"role_title": "Head of Transformation", "role_family": "transformation", "industry": "Financial Services", "employee_count": "1000-20000", "regulatory_environment": "Prudential regulation; transformation may be remediation-driven", "reporting_line": "CEO or COO", "board_exposure": "Program status reported to board and possibly regulator", "budget_scope": "Multi-year program budget", "business_situation": "A named transformation program with executive sponsorship, hard deadlines, and organizational resistance.", "expected_90_day_outcomes": "Program re-baselined honestly; governance reset; critical-path risks surfaced to sponsors.", "expected_first_year_outcomes": "Milestones delivered against the re-baselined plan; stakeholder confidence measurably recovered; benefits tracking live.", "preferred_leadership_style": "Delivery-obsessed, politically fluent, honest under pressure"}'::jsonb,
   '[{"competency_key": "transformation_delivery", "weight": 90, "rationale": "Delivery accountability is the entire role."},
     {"competency_key": "change_leadership", "weight": 85, "rationale": "The program fails without adoption."},
     {"competency_key": "enterprise_operating_experience", "weight": 80, "rationale": "Must deliver through committees, audit, and procurement."},
     {"competency_key": "cross_functional_influence", "weight": 80, "rationale": "Owns outcomes delivered by other people''s teams."},
     {"competency_key": "regulatory_compliance", "weight": 70, "rationale": "Remediation-driven programs answer to regulators."},
     {"competency_key": "executive_communication", "weight": 70, "rationale": "Honest status reporting sustains sponsorship."}]'::jsonb)
ON CONFLICT DO NOTHING;
